ALTER TABLE public.events DROP CONSTRAINT events_name_check; ALTER TABLE public.events ADD CONSTRAINT events_name_check CHECK(name IN('circle_link_opened','item_link_opened','signed_up','joined_circle','wish_added','item_posted','post_nudge_shown','item_shared','match_created','match_notification_sent','swipe_right','swipe_left','item_claimed','pickup_arranged','picked_up','thanked','claim_expired','item_expired','item_renewed','item_marked_donated','notify_me_tapped','clearout_interest_yes','clearout_interest_no','circle_created','circle_search_opened','circle_join_requested','circle_join_approved','circle_joined_from_search','circle_left','member_removed','profile_updated','custom_category_used','category_promoted','times_suggested','pickup_spot_shared','clearout_button_tapped'));
DO $m$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.passalong_legacy_action(text,jsonb)'::regprocedure) INTO body;
IF strpos(body,'ELSIF action=''event'' THEN')=0 THEN RAISE EXCEPTION 'event branch not found'; END IF;
body=replace(body,'ELSIF action=''event'' THEN','ELSIF action=''clearout_tap'' THEN IF NOT public.is_member((payload->>''circle_id'')::uuid) THEN RAISE EXCEPTION ''Join this circle first''; END IF; INSERT INTO public.events(user_id,circle_id,name) VALUES(u,(payload->>''circle_id'')::uuid,''clearout_button_tapped''); RETURN ''{}''::jsonb;
ELSIF action=''event'' THEN'); EXECUTE body; END $m$;